class IceCandidateSchema(BaseModel):
    candidate: str
    sdp_mid: Optional[str] = None
    sdp_mline_index: Optional[int] = None

@app.post("/api/v1/webrtc/rooms/{room_uuid}/ice-candidate")
async def post_ice_candidate(
    room_uuid: uuid.UUID,
    candidate: IceCandidateSchema,
    broker: WebRTCBroker = Depends(get_webrtc_broker),
    current_user: User = Depends(get_current_user),
    db: AsyncSession = Depends(get_async_db)
):
    participant = await db.execute(
        select(RoomParticipant).where(
            RoomParticipant.room_id == room_uuid,
            RoomParticipant.user_id == current_user.id
        )
    )
    if not participant.scalar_one_or_none():
        raise HTTPException(status_code=403, detail="Forbidden: Not an authorized participant of this room")
    room_active = await broker.is_room_active(room_uuid)
    if not room_active:
        raise HTTPException(status_code=404, detail="Meeting room not active")
    await broker.relay_candidate(room_uuid, candidate.model_dump(), sender_id=str(current_user.id))
    return {"relayed": True}
